   View view=find(activity.getWindow().getDecorView());if(view==null)throw new Exception("No actual PictureView");
   Field f=target.getClassLoader().loadClass("com.alensw.ui.view.j").getDeclaredField("b");f.setAccessible(true);Object picture=null;
   for(int i=0;i<45;i++){picture=f.get(view);if(picture!=null&&(mode==0||(picture.getClass().getField("d").getInt(picture)==2&&stats()[0]>baseline)))break;SystemClock.sleep(300);}
   if(picture==null)throw new Exception("No loaded picture");
   final Object pic=picture;JSONObject detail=new JSONObject().put("mode",mode).put("picture",pic.getClass().getName()).put("elapsed_ms",SystemClock.uptimeMillis()-began).put("stats",new JSONArray(stats()));checks.put(detail);
